fn rotate_right(list: &Vec<u32>, n: usize) -> Vec<u32> {
    let len = list.len();
    if len == 0 {
        return Vec::new(); // Shouldn't happen per problem, but defensive
    }
    
    let effective_rotation = n % len;
    let split_point = len - effective_rotation;
    
    // Create result by concatenating the two slices
    let mut result = Vec::with_capacity(len);
    result.extend_from_slice(&list[split_point..]);
    result.extend_from_slice(&list[..split_point]);
    
    result
}